head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.setData(["a", "b", "c"]);
};
scwin.trigger2_onclick = function(e) {
    dataList1.setData("[\"AA\",\"BB\",\"CC\"]");
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 3. 브라우저에서 Array 버튼을 클릭한다.
    //3. Click the Array button in your browser.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. a / b / c 로 데이터가 변경된다.
    //3. The data is changed to a / b / c.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_0').textContent == 'a'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_1').textContent == 'b'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_2').textContent == 'c'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. String 버튼을 클릭한다.
    //4. Click the String button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. AA / BB / CC 데이터로 변경된다.
    //4. Changed to AA / BB / CC data.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_0').textContent == 'AA'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_1').textContent == 'BB'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('wq_uuid_3_cell_0_2').textContent == 'CC'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    dataList1.setData([1, 2, 3, 4, 5, 6, 7, 8, 9]);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 01-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
